import pandas as pd
from pyspark.sql import functions as F

people = spark.createDataFrame(
    [(1, "ada"), (2, "grace"), (3, None)], "id INT, name STRING"
)

@F.udf("string")
def upper_py(s):
    return s.upper() if s is not None else None

@F.udf("string", useArrow=True)
def upper_arrow(s):
    return s.upper() if s is not None else None

@F.pandas_udf("string")
def upper_pandas(s: pd.Series) -> pd.Series:
    return s.str.upper()

for label, column in [
    ("built-in", F.upper("name")),
    ("Python UDF", upper_py("name")),
    ("Arrow Python UDF", upper_arrow("name")),
    ("pandas UDF", upper_pandas("name")),
]:
    print(label)
    people.select("id", column.alias("u")).filter(F.col("id") > 1).explain()
